from pypdf import PdfReader
r=PdfReader('inputs/borzoi.rnaseq.q1.pdf')
for i,p in enumerate(r.pages):
 t=p.extract_text() or ''
 if any(x in t.lower() for x in ['rna-seq','rna-seq coverage','coverage transform','arcsinh']):
  lines=t.splitlines()
  print(f'PAGE {i+1}')
  for j,l in enumerate(lines):
   if any(x in l.lower() for x in ['rna-seq','coverage','transform','arcsinh']):
    print('\\n'.join(lines[max(0,j-3):min(len(lines),j+4)]))
PY"

